// 加權 OR 而非嚴格 AND：沿用 candidate_lead.sql 的既有語意（該支註解記載
// 2026-08-07 live 驗證——嚴格 AND 會讓「分類與地區都對、但描述文字沒有字面
// 提到該關鍵字」的候選整筆消失，且回空時說不出原因）。
//
// category/region 用 ILIKE 部分比對而非精確比對：CRM1 的 產地 有 195 種細粒度值
// （台南東山、嘉義竹崎…），精確比對會漏掉「台南」這種泛稱查詢；CRM 與 CRM1 的分類
// 命名習慣也不一致（CRM 用複合詞如「雞肉／蛋品」，CRM1 用單詞如「水果」）。這條理由
// 原本記在 ai-service 已刪除的 candidate_lead.sql，隨資料源遷移到這裡——不要為了
// 「看起來更精確」把這兩個 ILIKE 簡化成 =，那會讓 CRM1 來源的列全部搜不到。
//
// status = 'ACTIVE' 這個述詞就是跨 lane 去重本身：已入駐（CONVERTED）的業者
// 出現在「找平台外的業者」本來就是錯的，不是去重問題（spec D4）。
//
// LIMIT 是服務端安全上限，不是相關性排序的截斷點——這條查詢刻意不排序
// （沒有 ORDER BY）：算分與排序是呼叫端（ai-service CandidateSearchUseCase.Search）
// 的責任，交給 DB 排序會撞上 sqlc/PostgreSQL 對輸出別名的 ORDER BY scoping 限制
// （見該檔同段落註解）。若這裡的 LIMIT 被呼叫端當成「回傳筆數」誤用（例如塞 10），
// 排序會變成先對任意 10 列算分再排序，而不是對全部命中列排序後取前 10 名——
// 這正是 C1 修過的那個回歸類別，之所以現在預設 500 不是 10，見 repository 的
// Search 方法。
func (q *Queries) SearchSellerProspects(ctx context.Context, arg SearchSellerProspectsParams) ([]SearchSellerProspectsRow, error) {
	rows, err := q.db.Query(ctx, searchSellerProspects,
		arg.Category,
		arg.Region,
		arg.Keywords,
		arg.CategoryIds,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchSellerProspectsRow{}
	for rows.Next() {
		var i SearchSellerProspectsRow
		if err := rows.Scan(
			&i.ID,
			&i.DisplayName,
			&i.VendorType,
			&i.Status,
			&i.OutreachStatus,
			&i.TaxID,
			&i.ConvertedStoreID,
			&i.ConvertedAt,
			&i.MatchEmail,
			&i.MatchPhone,
			&i.MatchDomain,
			&i.MatchSocial,
			&i.PublicEmail,
			&i.PublicPhone,
			&i.PublicWebsite,
			&i.PublicSocial,
			&i.Category,
			&i.Region,
			&i.ProductSummary,
			&i.Positioning,
			&i.ResearchSummary,
			&i.PriorityLetter,
			&i.PriorityStars,
			&i.LogoKey,
			&i.CoverKey,
			&i.LogoSourceUrl,
			&i.CoverSourceUrl,
			&i.MediaVersion,
			&i.CreatedByAccountID,
			&i.UpdatedByAccountID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.MergedIntoProspectID,
			&i.HitCategory,
			&i.HitRegion,
			&i.HitKeywords,
			&i.HitCategoryIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setSellerProspectArchived = `-- name: SetSellerProspectArchived :execrows
UPDATE seller_prospects
SET status                = CASE WHEN $1::boolean THEN 'ARCHIVED' ELSE 'ACTIVE' END,
    updated_by_account_id = $2,
    updated_at            = now()
WHERE id = $3::bigint
  AND (
    ($1::boolean       AND status = 'ACTIVE')
    OR (NOT $1::boolean AND status = 'ARCHIVED' AND merged_into_prospect_id IS NULL)
  )
`

