// 還原（archived = false）刻意加上 merged_into_prospect_id IS NULL：被合併的
// 列要還原就必須同時撤銷那次合併（含把邀請搬回去），本輪不提供反向操作。
// 封存（archived = true）只允許從 ACTIVE 出發——CONVERTED 由 chk_sp_converted
// 擋著，但那會是 500，所以這裡先擋成 rows = 0。
func (q *Queries) SetSellerProspectArchived(ctx context.Context, arg SetSellerProspectArchivedParams) (int64, error) {
	result, err := q.db.Exec(ctx, setSellerProspectArchived, arg.Archived, arg.OperatorAccountID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

